two_sum.optimal_solution:
def solve(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        if target - num in seen:
            return [seen[target-num], i]
        seen[num] = i

best_time_to_buy_stock.optimal_solution:
def solve(prices):
    min_p, profit = float('inf'), 0
    for p in prices:
        min_p = min(min_p, p)
        profit = max(profit, p - min_p)
    return profit

valid_anagram.optimal_solution:
def solve(s, t):
    from collections import Counter
    return Counter(s) == Counter(t)

maximum_subarray.optimal_solution:
def solve(nums):
    curr = best = nums[0]
    for n in nums[1:]:
        curr = max(n, curr+n)
        best = max(best, curr)
    return best

climbing_stairs.optimal_solution:
def solve(n):
    a, b = 1, 1
    for _ in range(n-1):
        a, b = b, a+b
    return b

coin_change.optimal_solution:
def solve(coins, amount):
    dp = [float('inf')] * (amount+1)
    dp[0] = 0
    for i in range(1, amount+1):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i-c]+1)
    return dp[amount] if dp[amount] != float('inf') else -1

valid_parentheses.optimal_solution:
def solve(s):
    stack, pairs = [], {')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{':
            stack.append(c)
        elif not stack or stack[-1] != pairs[c]:
            return False
        else:
            stack.pop()
    return not stack

number_of_islands.optimal_solution:
def solve(grid):
    if not grid: return 0
    count = 0
    def dfs(i,j):
        if i<0 or i>=len(grid) or j<0 or j>=len(grid[0]) or grid[i][j]!='1': return
        grid[i][j]='0'
        for di,dj in [(0,1),(0,-1),(1,0),(-1,0)]: dfs(i+di,j+dj)
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j]=='1': dfs(i,j); count+=1
    return count

house_robber.optimal_solution:
def solve(nums):
    prev2, prev1 = 0, 0
    for n in nums:
        prev2, prev1 = prev1, max(prev1, prev2+n)
    return prev1
